let playingTrack='lobby',musicRevision=0;
function switchRoomMusic(next){
 if(!ROOM_TRACKS[next]||playingTrack===next)return;
 const revision=++musicRevision,path=ROOM_TRACKS[next];playingTrack=next;
 if(!bgmStarted||bgm.paused){bgm.src=path;bgm.load();bgm.volume=bgmVolume;refreshBgmControls();return;}
 const begin=performance.now(),initial=bgm.volume;
 function fadeOut(now){if(revision!==musicRevision)return;const p=Math.min(1,Math.max(0,(now-begin)/310));bgm.volume=initial*(1-p);
  if(p<1){requestAnimationFrame(fadeOut);return;}
  bgm.pause();bgm.src=path;bgm.load();bgm.volume=0;
  if(bgmEnabled){bgm.play().then(()=>{const up=performance.now();function fadeIn(t){if(revision!==musicRevision)return;const q=Math.min(1,Math.max(0,(t-up)/520));bgm.volume=bgmVolume*q;if(q<1)requestAnimationFrame(fadeIn)}requestAnimationFrame(fadeIn);}).catch(()=>refreshBgmControls('음악 재생을 눌러 주세요.'))}
 }
 requestAnimationFrame(fadeOut);
}

