let soundEnabled=true,sfxCtx=null;
function playSound(kind){
 if(!soundEnabled)return;
 try{
  const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;
  if(!sfxCtx)sfxCtx=new AC();if(sfxCtx.state==='suspended')sfxCtx.resume();
  const notes={step:[[740,.065,.045]],success:[[523,.11,.12],[659,.11,.12],[784,.23,.15]],
   fail:[[280,.12,.07],[220,.18,.055]],locked:[[175,.11,.048],[145,.18,.033]],
   chapter:[[440,.11,.09],[587,.11,.10],[659,.11,.10],[880,.30,.13]],
   final:[[523,.1,.10],[659,.1,.10],[784,.13,.12],[1047,.17,.15],[1318,.4,.16]]};
  let at=sfxCtx.currentTime+.008;
  for(const [freq,duration,volume] of notes[kind]||notes.step){
   const osc=sfxCtx.createOscillator(),gain=sfxCtx.createGain();osc.type=kind==='fail'||kind==='locked'?'triangle':'sine';osc.frequency.setValueAtTime(freq,at);
   gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(Math.max(.0002,volume),at+.018);
   gain.gain.exponentialRampToValueAtTime(.0001,at+duration);osc.connect(gain);gain.connect(sfxCtx.destination);
   osc.start(at);osc.stop(at+duration+.015);at+=duration*.92;
  }
 }catch(e){console.warn('효과음 장치를 사용할 수 없음',e);}
}
