function maybeRoomScene(key){
 const scene=ROOM_ENTRY_SCENES[key];
 if(!scene||sceneSeen('room_intro_'+key)||room!==key||!$('#storyScene').hidden||!$('#intro').hidden)return;
 clearTimeout(roomSceneTimer);
 roomSceneTimer=setTimeout(()=>{if(room===key&&playable()){markScene('room_intro_'+key);playScene(scene);}},300);
}

