function sceneSeen(key){return !!(data.scenes&&data.scenes[key]);}
function markScene(key){data.scenes=data.scenes||{};if(data.scenes[key])return;data.scenes[key]=true;save();}
function speakerKeyFromName(name){
 if(name==='나')return 'player';
 if(name&&name.includes('윤'))return 'manager';
 if(name&&name.includes('서준'))return 'guide';
 if(name&&name.includes('민'))return 'archivist';
 if(name&&name.includes('하린'))return 'technician';
 return '';
}
function portraitHtmlFor(name){const key=speakerKeyFromName(name)||'manager';return `<img class="storyArt" src="assets/portraits/${key}.png" alt="" onerror="this.style.display='none';this.parentElement.textContent='✧'">`;}
function playScene(frames,{mode='cutscene',onFinish=null}={}){pressed.clear();clearTravel();$('#roomArrival').hidden=true;sceneFrames=frames;sceneMode=mode;sceneOnFinish=typeof onFinish==='function'?onFinish:null;storyIndex=0;$('#intro').hidden=true;$('#dialogue').hidden=true;$('#storyScene').hidden=false;renderStoryScene();updateTutorial();}
function talkToNpc(id){
 const npc=NPCS[id];if(!npc)return;tutorialTick('speak');
 data.npcTalks=data.npcTalks||{};const count=data.npcTalks[id]||0;data.npcTalks[id]=count+1;save();
 const local=MISSIONS.filter(m=>m.loc===room&&!data.done[m.id]);
 const next=local.find(unlocked)||MISSIONS.find(m=>unlocked(m)&&!data.done[m.id]);
 const impressions={
  manager:['한 장의 사진에는 한순간만 남아요. 여러 장을 나란히 놓으면 보이지 않던 변화가 드러나죠.','처음에 세운 설명을 고치는 건 실패가 아니에요. 더 많은 단서를 읽었다는 뜻이죠.'],
  technician:['빛이 남은 곳만 보지 말고 그림자의 경계도 살펴봐요. 현상할 때 가장 많은 이야기를 들려주는 부분이에요.','오늘은 조건을 하나씩 바꿔 볼까요? 무엇이 달라졌는지 알아야 필름 두 장을 제대로 비교할 수 있어요.'],
  guide:['하늘에서 무엇을 봤는지부터 말해 줘. 왜 그렇게 보였는지는 그다음에 모형과 함께 확인하자.','같은 별자리 옆에 찍힌 작은 점도, 날짜순으로 놓으면 길이 돼. 관측에는 기다림과 비교가 필요하지.'],
  archivist:['이곳의 책들은 정답순이 아니라 관측 날짜순으로 꽂혀 있어요. 설명은 기록을 비교한 다음에 붙이는 거죠.','내행성과 외행성을 나누는 기준은 지구 궤도예요. 기준 하나를 정하면 비슷한 그림도 다르게 읽힙니다.']
 };
 let hint;
 if(allDone())hint='아홉 장이 모두 돌아왔어요. 현상기는 다시 움직이고, 로비 오른쪽의 별 문양 문 너머로 숨은 기록실이 열렸어요.';
 else if(next&&next.loc===room)hint=`다음에는 ${WORLD.rooms[room].stations[next.id].label}을 살펴보세요. 「${next.name}」 기록이 기다리고 있어요.`;
 else if(next)hint=`이 방에서 지금 복원할 수 있는 기록은 살펴봤어요. 다음 단서는 ${ROOMS[next.loc].name}의 「${next.name}」에 있어요.`;
 else hint='되찾은 기록도 다시 살펴볼 수 있어요. 관측 수첩에서 지금까지의 설명을 확인해 보세요.';
 playScene([{who:npc.name,tag:WORLD.rooms[room].title,say:impressions[id][count%2]},{who:npc.name,tag:`다음 단서 / 복원 ${total()} · 9`,say:hint}]);
}

function maybeMissionIntro(id){if(sceneSeen('mission_intro_'+id))return; const v=MISSION_INTROS[id]; if(!v)return; markScene('mission_intro_'+id); showSpeech(v.name,v.text,v.icon||'💡');}
function missionOutro(id){const v=MISSION_OUTROS[id]||{name:NPCS.manager.name,text:STORY_CLUES[id]};const n=total();showSpeech(v.name,`${v.text} 현상기의 ${n}번째 표시등이 켜졌어요! 이제 ${9-n}개 남았어요.`, '📸');}
function maybeProgressScene(){
 if(chapterDone(1)&&!sceneSeen('chapter1_clear')){markScene('chapter1_clear'); setTimeout(()=>{playScene(CHAPTER1_SCENE,{onFinish:()=>{playSound('chapter');showSpeech(NPCS.manager.name,'첫 번째 봉인이 풀렸어요! 이제 행성 기록 다섯 장을 복원하면 중앙 현상기가 완전히 가동될 거예요.','📦');toast('첫 번째 봉인 해제 · 행성 기록 개방');}});},280); return;}
 if(allDone()&&!sceneSeen('all_done_story')){markScene('all_done_story'); setTimeout(()=>{playScene(FINAL_SCENE,{onFinish:()=>{playSound('final');showSpeech(NPCS.manager.name,'사진관 복구 완료! 중앙 현상기의 봉인이 해제됐어요. 로비 오른쪽의 물음표 문은 선택해서 조사할 수 있어요.','📸');toast('사진관 복구 완료 · 비밀 문 발견');}});},280);}
}
function updateTutorial(){const hud=$('#tutorialHud');if(hud)hud.hidden=true;if(window.STUDIO_WORLD&&typeof room==='string')updateWorldHud();}
function tutorialTick(key){if(!data.tutorial)data.tutorial={walk:false,speak:false,inspect:false};if(data.tutorial[key])return;data.tutorial[key]=true;save();updateTutorial();if(key==='inspect')showSpeech(NPCS.manager.name,'첫 번째 필름을 찾았군요. 이 사진을 복원하면 봉인 장치의 불빛 하나가 되살아날 거예요.','📷');}
function showStoryScene(){playScene(PROLOGUE,{mode:'prologue'});}
function renderStoryScene(){const d=sceneFrames[storyIndex];$('#storyEyebrow').textContent=d.tag;$('#storyName').textContent=d.who;$('#storyText').textContent=d.say;$('#storyCounter').textContent=String(storyIndex+1).padStart(2,'0')+' / '+String(sceneFrames.length).padStart(2,'0');$('#storyNext').textContent=storyIndex===sceneFrames.length-1?(sceneMode==='prologue'?'사진관 조사 시작 →':'대화 종료 →'):'다음 대화 →';$('#storyPortrait').innerHTML=portraitHtmlFor(d.who);$('#storyPortrait').style.filter=d.who==='???'?'grayscale(1) brightness(.4)':'none';}
function finishStory(){if($('#storyScene').hidden)return;pressed.clear();document.activeElement?.blur();const mode=sceneMode,cb=sceneOnFinish;sceneFrames=PROLOGUE;sceneMode='prologue';sceneOnFinish=null;$('#storyScene').hidden=true;if(mode==='prologue'){data.storySeen=true;save();announceRoom();updateTutorial();}else if(cb){cb();}lastFrame=performance.now();}
function advanceStory(){if($('#storyScene').hidden)return;if(++storyIndex>=sceneFrames.length)finishStory();else renderStoryScene();}
$('#storyNext').onclick=e=>{e.stopPropagation();advanceStory();};$('#storySkip').onclick=e=>{e.stopPropagation();finishStory();};
$('#replayStory').onclick=()=>{if(!$('#missionModal').hidden||!$('#secretModal').hidden)return;showStoryScene()};
window.addEventListener('keydown',e=>{if($('#storyScene').hidden)return;const k=e.key.toLowerCase();if(['enter',' ','e','escape'].includes(k)){e.preventDefault();e.stopImmediatePropagation();if(!e.repeat){if(k==='escape')finishStory();else advanceStory();}}},true);

function showSpeech(name,msg,icon='📷'){pressed.clear();clearTravel();$('#dialogue').hidden=false;$('#speakerName').textContent=name;$('#speakerText').textContent=msg;
const portrait=$('#speakerPortrait');const source=speakerKeyFromName(name);
if(source)portrait.innerHTML='<img src="assets/portraits/'+source+'.png" alt="" onerror="this.style.display=\'none\';this.parentElement.textContent=\'✧\'">';else portrait.textContent=icon;}
function toast(msg){const t=$('#toast');t.textContent=msg;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,2750)}
function updateUI(){
 $('#topProgress').textContent=`관측 도감 ${total()} / ${MISSIONS.length}`;
 $('#noteSub').textContent=allDone()?'모든 공식 관측 기록이 완성되었습니다. 이제 「? 방」으로 이어지는 숨은 기록실과 랭킹 보드를 확인해 보세요.':'사진관을 돌아다니며 NPC와 대화하고, 직접 관측 기록을 완성하세요. 사진마다 스토리 단서가 이어집니다.';
 $('#chapters').innerHTML=[1,2].map(c=>`<section class="chapterNote"><div class="chapterHeader"><b>CHAPTER ${String(c).padStart(2,'0')} · ${c===1?'식 현상':'행성의 겉보기 운동'}</b><span>${MISSIONS.filter(m=>m.ch===c&&data.done[m.id]).length}/${MISSIONS.filter(m=>m.ch===c).length}</span></div>${MISSIONS.filter(m=>m.ch===c).map((m,i)=>`<button class="quest ${data.done[m.id]?'complete':''}" data-mission="${m.id}"><span class="num">${data.done[m.id]?'✓':i+1}</span><span class="qt">${m.name}<br><span style="font-weight:400;color:#65807c">${m.sub}</span></span><span class="check">${data.done[m.id]?'✓':unlocked(m)?'⌾':'🔒'}</span></button>`).join('')}</section>`).join('');
 $('#logInfo').textContent=`수집한 관측 기록 ${total()}장 · 완료한 공식 활동 ${total()}/9개`;
 $('#secretStatus').hidden=!allDone();if(allDone())$('#secretStatus').textContent='오래된 사진관에 원래 없었던 「?」 문이 나타났습니다. 접수대 오른쪽 벽을 조사해 숨은 기록실로 들어가세요. 랭킹 보드는 그 안에서만 확인할 수 있습니다.';
 $$('.quest[data-mission]').forEach(b=>b.onclick=()=>{const m=MISSIONS.find(v=>v.id===b.dataset.mission);trackedMission=m.id;showSpeech('관측 도감',`${m.name}은(는) 「${ROOMS[m.loc].name}」에서 조사할 수 있어요. ${!unlocked(m)?'먼저 식 현상 기록 네 개를 복원해야 해요.':'그 장소로 걸어가 사진 가까이에서 E를 눌러 주세요.'}`,'📒');toast(m.loc===room?'지금 방 안의 반짝이는 기록을 찾으세요.':`이동 안내 · ${ROOMS[m.loc].name}`);updateDirection();});
 updateWorldHud();updateDirection();draw();
}
// V6 world presentation. The embedded ASTRA-7 engine below is intentionally untouched.
const WORLD = window.STUDIO_WORLD;
const layout = () => WORLD.rooms[room];
const gameCanvas = $('#worldCanvas'), ctx = gameCanvas.getContext('2d');
ctx.setTransform(2,0,0,2,0,0);
ctx.imageSmoothingEnabled = false;
const GAME_ASSETS = {};
const GAME_ASSET_PATHS = {
 player:'assets/characters/player.png',manager:'assets/characters/manager.png',
 technician:'assets/characters/technician.png',guide:'assets/characters/guide.png',archivist:'assets/characters/archivist.png',
 map_lobby:'assets/maps/lobby.webp',map_lobby_unlocked:'assets/maps/lobby_unlocked.webp',
 map_darkroom:'assets/maps/darkroom.webp',map_roof:'assets/maps/roof.webp',map_archive:'assets/maps/archive.webp',map_secret:'assets/maps/secret.png'
};
let assetLoaded=0;const assetErrors=[];
for (const [name,src] of Object.entries(GAME_ASSET_PATHS)) {
 const im=new Image();
 const complete=()=>{assetLoaded++;const el=$('#assetStatus');if(el)el.textContent=assetErrors.length?'일부 그림을 불러오지 못했어요 · 새로고침을 확인해 주세요':assetLoaded===Object.keys(GAME_ASSET_PATHS).length?'모든 관측 자료가 준비되었습니다':`관측 자료 준비 중 · ${assetLoaded}/${Object.keys(GAME_ASSET_PATHS).length}`;};
 im.onload=()=>{GAME_ASSETS[name]=im;complete();draw();};
 im.onerror=()=>{assetErrors.push(src);complete();console.warn('그림을 불러오지 못했습니다:',src);};im.src=src;
}
for(const id of ['player','manager','technician','guide','archivist']){const im=new Image();im.src=`assets/portraits/${id}.png`;}

function objects(){
 const plan=layout(), obs=[];
 for(const m of MISSIONS.filter(m=>m.loc===room)){
  const s=plan.stations[m.id];obs.push({id:m.id,type:'mission',x:s.anchor[0],y:s.anchor[1],vx:s.art[0],vy:s.art[1],name:s.label,missionName:m.name,locked:!unlocked(m),done:!!data.done[m.id]});
 }
 if(plan.npc){const n=plan.npc;obs.push({id:n.id,type:'npc',sprite:n.id,x:n.anchor[0],y:n.anchor[1],vx:n.anchor[0],vy:n.anchor[1]-53,name:NPCS[n.id].name});}
 if(room==='lobby'){const s=plan.stations.seal;obs.push({id:'seal',type:'device',x:s.anchor[0],y:s.anchor[1],vx:s.art[0],vy:s.art[1],name:allDone()?'복구된 중앙 현상기':'중앙 현상기'});}
 if(room==='secret'&&allDone())for(const id of ['scoreboard','rush','chaos']){const s=plan.stations[id];obs.push({id,type:'bonus',x:s.anchor[0],y:s.anchor[1],vx:s.art[0],vy:s.art[1],name:s.label});}
 for(const d of plan.details)obs.push({id:d.id,type:'inspect',x:d.anchor[0],y:d.anchor[1],vx:d.art[0],vy:d.art[1],name:d.label});
 for(const p of plan.portals){if(p.locked&&!allDone())continue;obs.push({id:'door-'+p.id,type:'door',dest:p.dest,x:p.x,y:p.y,vx:p.x,vy:p.y-28,name:p.label,portal:p});}
 return obs;
}
function roomPortals(){return layout().portals.filter(p=>!p.locked||allDone());}
function rect(x,y,w,h,fill,stroke='',radius=0){ctx.beginPath();ctx.roundRect(Math.round(x),Math.round(y),w,h,radius);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke();}}
function ell(x,y,rx,ry,col){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=col;ctx.fill();}
function circ(x,y,r,col){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=col;ctx.fill();}
function textAt(msg,x,y,size=15,col='#e8debd',align='center',weight=700){ctx.textAlign=align;ctx.font=`${weight} ${size}px 'Malgun Gothic',system-ui,sans-serif`;ctx.fillStyle=col;ctx.fillText(msg,x,y);ctx.textAlign='left';}
let animId=0,lastFrame=0,lastDraw=0,moving=false,portalBusy=false,portalGrace=performance.now()+900;
let travelPlan=[],travelTarget=null,arrivalTimer=0,roomSceneTimer=0,transitionSerial=0;
const pressed=new Set();
const reducedMotion=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function clearTravel(){travelPlan=[];travelTarget=null;}
function playable(){return !portalBusy&&directorPanel.hidden&&$('#intro').hidden&&$('#storyScene').hidden&&$('#dialogue').hidden&&$('#legacyPortal').hidden&&$('#missionModal').hidden&&$('#infoModal').hidden&&$('#secretModal').hidden;}
function blocked(x,y,includeNpc=true){
 const b=layout().bounds,r=WORLD.playerRadius;
 if(x<b.left||x>b.right||y<b.top||y>b.bottom)return true;
 if(layout().obstacles.some(([rx,ry,w,h])=>x+r>rx&&x-r<rx+w&&y+r>ry&&y-r<ry+h))return true;
 const n=layout().npc;
 return !!(includeNpc&&n&&Math.hypot(x-n.anchor[0],y-n.anchor[1])<23);
}
function directionToward(dx,dy){return Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');}
function nearestObject(){
 let best=null,score=Infinity;
 for(const o of objects()){
  const d=Math.hypot(player.x-o.x,player.y-o.y),range=o.type==='door'?78:o.type==='npc'?76:68;
  if(d>range)continue;
  const facing=directionToward(o.x-player.x,o.y-player.y)===player.dir;
  const s=d+(o.type==='door'?19:0)-(facing?7:0);
  if(s<score){best=o;score=s;}
 }
 return best;
}
function updateDirection(){
 const o=nearestObject(),p=$('#worldPrompt');
 p.classList.toggle('near',!!o);p.hidden=!o||!playable();
 if(o){
  let action=o.type==='door'?'걸어서 이동':o.type==='npc'?'이야기하기':o.done?'기록 다시 보기':'조사하기';
  if(o.type==='door')action='걸어서 이동';
  if(o.locked)action='식 현상 기록 4개 복원 필요';
  if(o.type==='bonus')action=o.id==='scoreboard'?'기록 확인':'도전하기';
  p.innerHTML=`<b>${o.type==='door'?'이동':'E'}</b><span>${esc(o.name)}<small>${action}</small></span>`;
 }
 $('#roomNav').innerHTML='';
}
function drawSprite(name,x,y,dir='down',frame=1){
 const im=GAME_ASSETS[name];if(!im?.naturalWidth)return;
 const s=WORLD.sprite,row={down:0,left:1,right:2,up:3}[dir]||0;
 const sw=im.naturalWidth/3,sh=im.naturalHeight/4;
 ctx.save();ctx.imageSmoothingEnabled=false;
 // Sprite alpha baseline is normalized to y=119 in each 96×128 cell.
 ctx.drawImage(im,Math.max(0,Math.min(2,frame))*sw,row*sh,sw,sh,Math.round(x-s.drawWidth/2),Math.round(y-s.drawHeight*s.footY/s.cellHeight),s.drawWidth,s.drawHeight);ctx.restore();
}
function drawMapImage(t){
 const im=GAME_ASSETS[room==='lobby'&&allDone()?'map_lobby_unlocked':'map_'+room]||GAME_ASSETS['map_'+room];
 if(im?.naturalWidth){ctx.imageSmoothingEnabled=false;ctx.drawImage(im,0,0,960,540);}
 else{rect(0,0,960,540,'#182735');rect(0,268,960,272,'#604839');for(let y=276;y<540;y+=24)rect(0,y,960,1,'#342c30');textAt('관측 공간을 준비하고 있어요',480,220,22,'#e3c99b');}
 // Light and dust stay in the background plane; equipment is already painted into it.
 ctx.save();
 for(const [x,y,rgb,r] of layout().lights){const g=ctx.createRadialGradient(x,y,1,x,y,r);g.addColorStop(0,`rgba(${rgb},.055)`);g.addColorStop(1,`rgba(${rgb},0)`);ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2);}
 if(!reducedMotion())for(let i=0;i<13;i++){const x=115+(i*71+Math.sin(t/5000+i)*17)%740,y=100+(i*43+Math.cos(t/4500+i)*13)%330;ctx.globalAlpha=.14+.1*Math.sin(t/2200+i);ctx.fillStyle=room==='roof'?'#c8d9ec':'#f9d89c';ctx.fillRect(Math.round(x),Math.round(y),1,1);}
 ctx.restore();
}
function drawStudioSeal(t){
 if(room!=='lobby')return;
 const s=layout().seal;
 MISSIONS.forEach((m,i)=>{const lit=!!data.done[m.id];ctx.save();if(lit){ctx.shadowColor='#ffd995';ctx.shadowBlur=7;}circ(s.x+i*s.gap,s.y,s.radius,lit?'#f5dea1':'#182b2a');if(lit)circ(s.x+i*s.gap-.5,s.y-.5,.8,'#fff7dc');ctx.restore();});
}
function drawMarkers(t){
 const nearest=nearestObject(),idle=!$('#intro').hidden||!$('#legacyPortal').hidden;
 if(idle)return;
 for(const o of objects()){
  const near=nearest?.id===o.id;
  if(o.type==='npc'||o.type==='door')continue;
  if(o.type==='inspect'&&!near)continue;
  const x=o.vx,y=o.vy,locked=o.locked,alpha=near?1:locked?.32:o.done?.48:.78;
  ctx.save();ctx.globalAlpha=alpha;
  const c=o.done?'#a7d7b7':locked?'#bcae91':'#ffe3a5';ctx.fillStyle=c;
  const pulse=reducedMotion()?0:Math.sin(t/650+x)*1.2;
  const size=near?5:3;
  ctx.fillRect(Math.round(x)-size,Math.round(y+pulse),size*2+1,1);
  ctx.fillRect(Math.round(x),Math.round(y+pulse)-size,1,size*2+1);
  if(near){ctx.strokeStyle=c;ctx.lineWidth=1;ctx.strokeRect(x-13,y-12,26,25);}
  if(o.done){ctx.fillStyle=c;ctx.fillRect(x+8,y+9,3,2);ctx.fillRect(x+10,y+6,2,4);}
  ctx.restore();
 }
 // Destination feedback is on the floor, never a freestanding map prop.
 if(travelPlan.length){const p=travelPlan[travelPlan.length-1];ctx.save();ctx.globalAlpha=.65;ctx.strokeStyle='#f3d6a0';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x,p.y-4);ctx.lineTo(p.x+6,p.y);ctx.lineTo(p.x,p.y+4);ctx.lineTo(p.x-6,p.y);ctx.closePath();ctx.stroke();ctx.restore();}
}
function drawCharacters(t){
 const actors=[{id:'player',x:player.x,y:player.y,dir:player.dir,frame:moving?([0,1,2,1][Math.floor(player.step*5)%4]):1}];
 if(layout().npc){const n=layout().npc,d=Math.hypot(player.x-n.anchor[0],player.y-n.anchor[1]);actors.push({id:n.id,x:n.anchor[0],y:n.anchor[1],dir:d<150?directionToward(player.x-n.anchor[0],player.y-n.anchor[1]):n.facing,frame:1});}
 actors.sort((a,b)=>a.y-b.y);
 for(const a of actors){ell(a.x,a.y-1,18,5,'#101a276a');drawSprite(a.id,a.x,a.y,a.dir,a.frame);}
}
function draw(t=performance.now()){
 if(!layout())return;
 drawMapImage(t);drawStudioSeal(t);drawMarkers(t);drawCharacters(t);
 if(gameCanvas.style.transform)gameCanvas.style.transform='';
}
function inTrigger(p){const r=p.trigger;return player.x>=r.x&&player.x<=r.x+r.w&&player.y>=r.y&&player.y<=r.y+r.h;}
function checkPortalWalk(){if(portalBusy||performance.now()<portalGrace)return;for(const p of roomPortals())if(inTrigger(p)){walkThroughPortal(p.dest,p);return;}}
function arriveFacing(source,dest){return 'down';}
function walkThroughPortal(destination,portal=null){
 if(portalBusy||performance.now()<portalGrace||!playable())return;
 const p=portal||roomPortals().find(p=>p.dest===destination);if(!p)return;
 if(destination==='secret'&&!allDone())return;
 const source=room,fade=$('#doorFade'),serial=++transitionSerial;
 const fast=reducedMotion(),cover=fast?80:250,uncover=fast?90:280;
 portalBusy=true;pressed.clear();clearTravel();$('#worldPrompt').hidden=true;$('#roomArrival').hidden=true;
 fade.hidden=false;$('#transitionName').textContent=WORLD.rooms[destination].title;$('#transitionNote').textContent=WORLD.rooms[destination].note;
 fade.dataset.direction=p.face||'up';requestAnimationFrame(()=>fade.classList.add('visible'));playSound('door');
 setTimeout(()=>{
  if(serial!==transitionSerial)return;
  changeRoom(destination,[p.entry.x,p.entry.y],{announce:false,scene:false});
  player.dir=arriveFacing(source,destination);rememberPosition();
  setTimeout(()=>fade.classList.remove('visible'),fast?20:80);
  setTimeout(()=>{
   if(serial!==transitionSerial)return;
   fade.hidden=true;portalBusy=false;portalGrace=performance.now()+650;pressed.clear();announceRoom();
   if(destination==='secret'&&!sceneSeen('secret_intro')){markScene('secret_intro');playScene(SECRET_SCENE);}else maybeRoomScene(destination);
   updateDirection();
  },uncover+100);
 },cover);
}
function move(dx,dy,pixels=11){
 if(!playable())return false;
 const len=Math.hypot(dx,dy)||1,nx=dx/len,ny=dy/len;let ok=false;
 if(!blocked(player.x+nx*pixels,player.y)){player.x+=nx*pixels;ok=true;}
 if(!blocked(player.x,player.y+ny*pixels)){player.y+=ny*pixels;ok=true;}
 if(dx||dy)player.dir=directionToward(dx,dy);
 if(ok){player.step+=pixels/42;tutorialTick('walk');checkPortalWalk();updateDirection();const now=performance.now();if(now-lastPositionWrite>1500){lastPositionWrite=now;rememberPosition();}}
 return ok;
}
function findWalkPath(tx,ty){
 const cell=12,cols=81,rows=46,toId=(x,y)=>y*cols+x,points=new Map(),parent=new Map();
 const gx=Math.round(tx/cell),gy=Math.round(ty/cell),sx=Math.round(player.x/cell),sy=Math.round(player.y/cell);
 const start=toId(sx,sy),goal=toId(gx,gy),queue=[start];points.set(start,[sx,sy]);parent.set(start,-1);
 let found=-1,best=start,bestDist=Infinity;
 for(let i=0;i<queue.length;i++){
  const id=queue[i],[x,y]=points.get(id),d=Math.hypot(x*cell-tx,y*cell-ty);
  if(d<bestDist){bestDist=d;best=id;}if(id===goal||d<9){found=id;break;}
  for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){
   const xx=x+dx,yy=y+dy,nid=toId(xx,yy);if(xx<0||yy<0||xx>=cols||yy>=rows||parent.has(nid)||blocked(xx*cell,yy*cell))continue;
   parent.set(nid,id);points.set(nid,[xx,yy]);queue.push(nid);
  }
 }
 if(found===-1){if(bestDist>35)return [];found=best;}
 const path=[];for(let id=found;id!==start&&id!==-1;id=parent.get(id)){const [x,y]=points.get(id);path.push({x:x*cell,y:y*cell});}
 path.reverse();if(!blocked(tx,ty)&&bestDist<20)path.push({x:tx,y:ty});return path;
}
function startWalkingTo(x,y,target=null){
 const path=findWalkPath(x,y);
 if(!path.length){toast('걸을 수 있는 바닥이나 가까운 장비를 선택해 주세요.');return;}
 pressed.clear();travelPlan=path;travelTarget=target;
}
function handleWorldPointer(e){
 if(!playable()||e.target!==gameCanvas)return;
 const r=gameCanvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*960,y=(e.clientY-r.top)/r.height*540;
 const target=objects().filter(o=>Math.hypot(o.vx-x,o.vy-y)<(o.type==='npc'?43:35)||Math.hypot(o.x-x,o.y-y)<28).sort((a,b)=>Math.hypot(a.vx-x,a.vy-y)-Math.hypot(b.vx-x,b.vy-y))[0];
 if(target){
  if(target.type==='door'){startWalkingTo(target.x,target.y,target.id);return;}
  if(Math.hypot(player.x-target.x,player.y-target.y)<74){clearTravel();hotspot(target.id);return;}
  let ax=target.x,ay=target.y;
  if(target.type==='npc'){const dx=player.x-ax,dy=player.y-ay,d=Math.hypot(dx,dy)||1;ax+=dx/d*47;ay+=dy/d*47;}
  startWalkingTo(ax,ay,target.id);return;
 }
 if(!blocked(x,y))startWalkingTo(x,y);else toast('반짝이는 장비를 누르거나 빈 바닥을 선택해 주세요.');
}
function frame(now){
 const dt=Math.min(.04,Math.max(0,(now-(lastFrame||now))/1000));lastFrame=now;moving=false;
 if(playable()){
  let dx=0,dy=0;if(pressed.has('w')||pressed.has('arrowup'))dy--;if(pressed.has('s')||pressed.has('arrowdown'))dy++;if(pressed.has('a')||pressed.has('arrowleft'))dx--;if(pressed.has('d')||pressed.has('arrowright'))dx++;
  if(dx||dy){clearTravel();moving=move(dx,dy,dt*184);}
  else if(travelPlan.length){
   const goal=travelPlan[0],d=Math.hypot(goal.x-player.x,goal.y-player.y);
   if(d<3){travelPlan.shift();if(!travelPlan.length){const target=travelTarget;travelTarget=null;if(target){const o=objects().find(o=>o.id===target);if(o&&o.type!=='door'&&Math.hypot(player.x-o.x,player.y-o.y)<82)hotspot(o.id);}}}
   else{moving=move(goal.x-player.x,goal.y-player.y,Math.min(d,dt*184));if(!moving&&!portalBusy)clearTravel();}
  }
 }else if(!$('#intro').hidden||!$('#legacyPortal').hidden||!$('#storyScene').hidden||!$('#missionModal').hidden)clearTravel();
 if($('#legacyPortal').hidden&&(now-lastDraw>33)){draw(now);lastDraw=now;}
 animId=requestAnimationFrame(frame);
}
function safePosition(requested){
 const defaults=layout().spawn,[x,y]=requested||defaults;
 if(!blocked(x,y)&&!roomPortals().some(p=>{const q=p.trigger;return x>=q.x-10&&x<=q.x+q.w+10&&y>=q.y-10&&y<=q.y+q.h+10;}))return [x,y];
 for(let r=0;r<360;r+=12)for(let a=0;a<Math.PI*2;a+=Math.PI/12){const nx=defaults[0]+Math.cos(a)*r,ny=defaults[1]+Math.sin(a)*r;if(!blocked(nx,ny))return [nx,ny];}
 return defaults;
}
function announceRoom(){
 if(!$('#intro').hidden)return;
 const el=$('#roomArrival'),l=layout();clearTimeout(arrivalTimer);
 $('#arrivalCode').textContent=l.code;$('#arrivalName').textContent=l.title;$('#arrivalNote').textContent=l.note;el.hidden=false;
 arrivalTimer=setTimeout(()=>el.hidden=true,2300);
}
function updateWorldHud(){
 const l=layout();$('#locationEyebrow').textContent=l.code;$('#locationTitle').textContent=l.title;$('#fieldCount').textContent=`${total()} / 9`;
 const hint=$('#journeyHint');hint.hidden=!!data.tutorial?.walk&&!!data.tutorial?.inspect;
 hint.textContent='WASD / 방향키로 걷기 · E 조사 · 바닥이나 장비를 클릭해도 좋아요';
}
function changeRoom(next,entry=null,options={}){
 if(!ROOMS[next]||(next==='secret'&&!allDone()))return;
 clearTimeout(roomSceneTimer);room=next;switchRoomMusic(next);pressed.clear();clearTravel();
 if(!Array.isArray(data.seen))data.seen=[];if(!data.seen.includes(next))data.seen.push(next);
 [player.x,player.y]=safePosition(entry);player.dir='down';portalGrace=performance.now()+650;
 rememberPosition();$('#dialogue').hidden=true;$('#worldCode').textContent=ROOMS[next].code;$('#worldName').textContent=ROOMS[next].name;
 updateWorldHud();updateDirection();draw();if(!$('#intro').hidden)updateResumeButton();
 if(options.announce!==false)announceRoom();if(options.scene!==false)maybeRoomScene(next);
}

function hotspot(id){
 if(id.startsWith('door-'))return;
 const detail=layout().details.find(d=>d.id===id);
 if(detail){playScene(detail.lines.map((say,i)=>({who:i===0?'나':detail.who,tag:detail.label,say})));return;}
 if(NPCS[id]){talkToNpc(id);return;}
  if(id==='seal'){playSound(allDone()?'success':'locked');playScene([
   {who:'나',tag:'중앙 현상기 / '+total()+' of 9',say:allDone()?'아홉 표시등이 모두 켜졌어. 사진관은 다시 숨을 쉬고 있어.':`아홉 표시등 가운데 ${total()}개가 켜졌어. 아직 ${9-total()}개의 사진을 더 복원해야 기계가 완전히 작동할 거야.`},
   {who:'사진관 관리인 · 윤',tag:'봉인의 단서',say:allDone()?'문이 열렸어요. 오른쪽 벽에는 새로운 물음표 문도 나타났답니다.':(!chapterDone(1)?'식 현상 사진 네 장을 먼저 조사해 주세요. 빛과 그림자의 관계를 알아야 첫 잠금쇠가 풀려요.':'첫 번째 잠금쇠는 풀렸어요. 이제 행성 사진 다섯 장을 복원해 마지막 잠금을 해제해 봅시다.')}
  ]);return;}
 if(id==='secret'){if(allDone())walkThroughPortal('secret');return;}
 if(id==='scoreboard'){openSecret();return;}
 if(id==='rush'){launchOriginalArena('rush');return;}
 if(id==='chaos'){liquidEntrance(()=>launchOriginalArena('chaos'));return;}
 const m=MISSIONS.find(v=>v.id===id);if(!m)return;
 if(!unlocked(m)){playSound('locked');showSpeech(NPCS.manager.name,'이 행성 기록은 아직 봉인되어 있어요. 일식과 월식 기록 네 개를 모두 복원하면 조사할 수 있어요.','📷');return;}
 trackedMission=m.id;if(m.id==='e1')tutorialTick('inspect');enterMissionThroughNpc(m);
}
