function enterMissionThroughNpc(m){
 const local=LOCAL_PURPOSES[m.id];
 if(sceneSeen('mission_intro_'+m.id)){openMission(m.id);return;}
 markScene('mission_intro_'+m.id);
 playScene([
  {who:NPCS[local.npc].name,tag:local.device,say:local.text},
  {who:NPCS[local.npc].name,tag:'함께 예상해 봐요 / '+m.sub,say:TEACHER_QUESTIONS[m.id]+' 예상한 뒤 조건을 바꾸어 비교해 봅시다.'}
 ],{onFinish:()=>openMission(m.id)});
}

