 function release(){pressed.delete(key);b.classList.remove('held');}
 b.addEventListener('pointerdown',e=>{e.preventDefault();if(!playable())return;b.setPointerCapture(e.pointerId);pressed.add(key);b.classList.add('held');const [dx,dy]=b.dataset.step.split(',').map(Number);move(dx,dy,10);});
