function e1UI(){const r=e1Records(),isNew=state.phase==='삭',good=isNew&&state.node<=12,miss=isNew&&state.node>=40;
 const scene=e1SceneSvg();
 const row=(id,title,txt)=>`<div class="e1-capture ${r[id]?'complete':''}"><b>${r[id]?'✓ ':''}${title}</b><small>${r[id]?`삭 · 교점 상대값 ${r[id].node} · ${txt}`:'아직 기록 없음'}</small></div>`;
 const control=`<div class="e1-steps">${[['예측',Boolean(state.prediction)],['두 조건 비교',Boolean(r.miss&&r.hit)],['근거 선택',state.evidence==='inclination'],['설명 수정',state.revised==='near']].map(([t,done],i)=>`<span class="${done?'ready':'pending'}">${done?'✓':i+1} ${t}</span>`).join('')}</div>
 <section class="e1-step"><h3>① 먼저 예상하기</h3><p>두 사진 모두 ‘삭’이라고 기록돼 있어요. 그렇다면 일식도 두 번 모두 발생할까요?</p>${e1Opt(E1_PREDICT,'prediction')}</section>
 <section class="e1-step"><h3>② 두 조건을 비교해 사진으로 남기기</h3><p>달의 위상과 교점으로부터의 상대적인 차이를 조절해 보세요. 다른 조건을 고정해 비교하는 것이 중요해요.</p>
 ${field('달의 위상',selectField('phase',['삭','상현','망']))}${field(`교점에서 벗어난 정도: ${state.node} (0=가까움, 100=멀어짐 · 모형 지표)`,slider('node',0,100,1))}
 <div class="e1-experiment">${good?'☀ 지금은 <b>일식이 가능한 조건</b>에 가까워요.':miss?'○ 지금은 <b>삭이지만 그림자가 지구를 빗나가는 조건</b>이에요.':'조건을 바꿔 「삭 + 교점에서 멀리」와 「삭 + 교점 가까이」를 각각 비교해 보세요.'}</div>
 <button type="button" class="e1-help" data-e1-help>💡 관측 조건 맞추기 도움</button>
 <button type="button" class="e1-record-btn" data-e1-record="${good?'hit':miss?'miss':''}" ${!state.prediction||(!good&&!miss)?'disabled':''}>📸 ${good?'사진 B 기록 · 일식 가능':miss?'사진 A 기록 · 일식 없음':'조건을 맞추면 기록 가능'}</button>
 <div class="e1-captures">${row('miss','A · 삭인데 일식 없음','그림자가 지구를 비껴감')}${row('hit','B · 삭이며 일식 가능','교점 부근에서 정렬')}</div></section>
 <section class="e1-step"><h3>③ 두 사진을 설명하는 근거 선택</h3><p>날씨 때문에 가려진 태양과 실제 일식을 구분하고, 두 사진의 조건을 설명하는 이유를 골라 봐요.</p>${e1Opt(E1_EVIDENCE,'evidence')}${state.evidence&&state.evidence!=='inclination'?'<p style="color:#ae6441">그 설명으로는 두 삭의 차이를 설명하기 어려워요. 궤도면과 교점을 다시 살펴봐요.</p>':''}</section>
 <section class="e1-step"><h3>④ 처음 생각을 수정하고 근거를 남기기</h3><p>처음 예측을 바꿔도 괜찮아요. 관측 결과와 맞는 설명을 다시 고르세요.</p>${e1Opt(E1_REVISED,'revised')}
 <p><label for="e1Note" style="font-weight:800;color:#2e6665">나만의 관측 메모 (선택)</label></p><textarea id="e1Note" class="e1-note" data-e1-note placeholder="예: 삭은 두 번 모두 같았지만 교점과의 관계가 달랐다." maxlength="420">${esc(state.note||'')}</textarea><p>문장 표현은 자동 채점하지 않아요. 관측 자료를 근거로 생각을 정리해 봐요.</p></section>`;
 const observation=`<div class="e1-result-grid"><div><b>사진 A · ${r.miss?'기록 완료':'미확보'}</b><p>${r.miss?'삭 · 교점에서 멀리 → 일식 없음':'달이 삭인데도 일식이 없는 경우를 찾아보세요.'}</p></div><div><b>사진 B · ${r.hit?'기록 완료':'미확보'}</b><p>${r.hit?'삭 · 교점 가까이 → 일식 가능':'삭이고 교점 부근인 경우를 찾아보세요.'}</p></div></div><div class="e1-results-caption">${e1NextFeedback()}<br>※ 모형의 ‘일식 가능’은 주어진 중앙 관측선 조건에 대한 개념적 판정입니다. 실제 관측 지역·날짜를 예측하는 계산이 아닙니다.</div>${r.miss&&r.hit?'<div class="e1-photo-note"><strong>복원 단서</strong> 두 음화의 뒷면에는 같은 접수번호가 남아 있어요. 19:47은 촬영 시각이 아니라 접수 장부의 시각일까요?</div>':''}`;
 return {diagram:scene,control,ob:observation};
}

