 control=field(`관측 지점 · ${off>0?'+':''}${off}`,slider('observer',-100,100,1))+field('현 위치의 관측 결과',`<b style="color:#387a78">${kind}</b>`)+field('관측자의 위치를 어떻게 해석할까?',options(state.region,[['본영','본영에서는 개기일식'],['반영','반영에서는 개기일식'],['밖','모든 지역에서 같은 일식']]));
