function liquidEntrance(after){
 const canvas=$('#inkScene'),c=canvas.getContext('2d');canvas.classList.add('active');
 const scale=Math.min(devicePixelRatio||1,1.5);let w=Math.floor(innerWidth*scale),h=Math.floor(innerHeight*scale);canvas.width=w;canvas.height=h;canvas.style.width='100%';canvas.style.height='100%';
 const start=performance.now(),fill=970,hold=220,recede=980;let swapped=false;
 const ease=p=>1-(1-Math.min(1,Math.max(0,p)))**3;
 function step(now){const t=now-start;let p=t<fill?ease(t/fill):t<fill+hold?1:1-ease((t-fill-hold)/recede);
  if(t>=fill&&!swapped){swapped=true;after();}
  c.clearRect(0,0,w,h);const y=h*(1-p);c.fillStyle='#030408';c.beginPath();c.moveTo(0,h);c.lineTo(0,y);
  for(let x=0;x<=w+12;x+=12){const wave=9*Math.sin(x/65+t*.003)+5*Math.sin(x/25-t*.006);c.lineTo(x,y+wave*scale)}c.lineTo(w,h);c.closePath();c.fill();
  c.fillStyle='rgba(140,145,160,.10)';for(let i=0;i<19;i++){const x=(i*127+t*.06)%w,dy=y+20+(i*73)%230;if(dy<h){c.beginPath();c.arc(x,dy,(i%3+2)*scale,0,Math.PI*2);c.fill()}}
  if(t<fill+hold+recede)requestAnimationFrame(step);else{c.clearRect(0,0,w,h);canvas.classList.remove('active');}
 }
 requestAnimationFrame(step);
}
