(()=>{'use strict';
const get=id=>document.getElementById(id);
const title=get('intro'),settings=get('titleSettings'),help=get('titleHelp'),music=get('musicToggle'),volume=get('musicVolume');
function hideMenus(){settings.hidden=true;help.hidden=true;}
function syncSound(){get('titleMusicToggle').textContent=music.getAttribute('aria-pressed')==='false'?'♪ 배경음악 꺼짐':'♪ 배경음악 켜짐';get('titleVolume').value=volume.value;}
get('titleSettingsOpen').addEventListener('click',()=>{hideMenus();syncSound();settings.hidden=false;get('titleSettingsClose').focus();});
get('titleSettingsClose').addEventListener('click',()=>{settings.hidden=true;get('titleSettingsOpen').focus();});
get('titleHelpClose').addEventListener('click',()=>{help.hidden=true;get('howTo').focus();});
// Override older 2-second toast behavior with a stable in-title instruction panel.
get('howTo').onclick=()=>{hideMenus();help.hidden=false;get('titleHelpClose').focus();};
get('titleMusicToggle').addEventListener('click',()=>{music.click();syncSound();});
get('titleVolume').addEventListener('input',e=>{volume.value=e.target.value;volume.dispatchEvent(new Event('input',{bubbles:true}));});
get('titleFullscreen').addEventListener('click',()=>get('teacherFullscreen').click());
function showTitle(){
 if(!get('missionModal').hidden||!get('secretModal').hidden||!get('storyScene').hidden||!get('legacyPortal').hidden){return false;}
 hideMenus();title.hidden=false;
 const current=window.STARLIGHT_TEST;
 if(current){const progress=current.getProgress?.()||0,seen=current.getStorySeen?.()||false;
 get('resumeGame').hidden=!(seen||progress);
 const roomNames={lobby:'사진관',darkroom:'암실',roof:'옥상',archive:'자료실',secret:'비밀방'};
 const room=roomNames[current.getRoom?.()]||'사진관';const snap=get('resumeSnapshot');
 snap.hidden=!(seen||progress);if(seen||progress)snap.textContent=`저장된 기록 ${progress}/9장 · ${room}에서 이어하기 가능`;
 }
 title.querySelector('#startGame').focus();return true;
}
const panel=get('directorPanel');if(panel){
 const btn=document.createElement('button');btn.id='returnToTitle';btn.type='button';btn.className='titleBackDirector';btn.textContent='⌂ 타이틀 화면으로';
 btn.style.cssText='background:#533d34;border:1px solid #e0bb84;border-radius:7px;color:#ffe7c6;padding:10px 15px;min-height:42px;font-size:15px;font-weight:900;cursor:pointer';
 btn.addEventListener('click',()=>{if(showTitle()){panel.hidden=true;get('directorToggle').setAttribute('aria-expanded','false');} });panel.appendChild(btn);
}
// RPG Maker style menu focus without interfering with gameplay.
title.addEventListener('keydown',e=>{
 if(title.hidden)return;
 if(e.key==='Escape'){if(!settings.hidden){settings.hidden=true;get('titleSettingsOpen').focus();e.preventDefault();}else if(!help.hidden){help.hidden=true;get('howTo').focus();e.preventDefault();}return;}
 if(e.key==='ArrowUp'||e.key==='ArrowDown'){
  const scope=settings.hidden?(help.hidden?title.querySelector('.titleMenu'):help):settings;
  const options=[...scope.querySelectorAll('button:not([hidden]):not([disabled])')];
  if(!options.length)return;
  const i=options.indexOf(document.activeElement);const next=(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;
  options[next].focus();e.preventDefault();
 }
});
if(!title.hidden)get('startGame').focus();syncSound();
})();
